-- Rollback of 2026-11-11-darwin-core-multimedia-medium.sql: the view darwin_core_multimedia as it stood on production
-- on 2026-11-11 before the change (SHOW CREATE VIEW, 10:41 Pacific): the www.antweb.org _high.jpg addresses and the
-- copyright line as rights holder. Safe to run twice.

CREATE OR REPLACE ALGORITHM=UNDEFINED DEFINER=`antweb`@`localhost` SQL SECURITY DEFINER VIEW `darwin_core_multimedia` AS select concat(_utf8mb3'CAS:ANTWEB:',`im`.`image_of_id`) AS `occurrenceid`,`im`.`image_of_id` AS `catalognumber`,concat('https://www.antweb.org/images/',`im`.`image_of_id`,'/',`im`.`image_of_id`,'_',`im`.`shot_type`,'_',`im`.`shot_number`,'_high.jpg') AS `imageurl`,`im`.`shot_type` AS `shot_type`,`im`.`shot_number` AS `shot_number`,concat('https://www.antweb.org/specimenImages.do?name=',`im`.`image_of_id`) AS `references`,concat(`im`.`image_of_id`,convert((case `im`.`shot_type` when 'd' then ' dorsal' when 'h' then ' head' when 'l' then ' label' when 'p' then ' profile' end) using utf8mb3),' view ',`im`.`shot_number`) AS `title`,`li`.`license` AS `license`,nullif(`cr`.`copyright`,'') AS `rightsHolder`,nullif(`ar`.`name`,'') AS `creator` from (((`image` `im` left join `license` `li` on((`im`.`license` = `li`.`id`))) left join `copyright` `cr` on((`im`.`copyright` = `cr`.`id`))) left join `artist` `ar` on((`im`.`artist` = `ar`.`id`))) order by concat('https://www.antweb.org/images/',`im`.`image_of_id`,'/',`im`.`image_of_id`,'_',`im`.`shot_type`,'_',`im`.`shot_number`,'_high.jpg');
